CREATE TABLE IF NOT EXISTS SchemaVersion(Version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS Customer(Id GUID PRIMARY KEY,Name TEXT,Mobile TEXT,UpdatedAtUtc DATETIME,IsDeleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS Intake(Id GUID PRIMARY KEY,Number INTEGER,Trade INTEGER,Stage INTEGER,CustomerId GUID,DeviceType TEXT,Brand TEXT,Model TEXT,Serial TEXT,Complaint TEXT,Accessories TEXT,EstimateRial INTEGER,AdvanceRial INTEGER,Technician TEXT,CreatedAtUtc DATETIME,DeliveredAtUtc DATETIME,UpdatedAtUtc DATETIME,IsDeleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS BoardPin(Id GUID PRIMARY KEY,IntakeId GUID,X REAL,Y REAL,Kind INTEGER,Note TEXT,UpdatedAtUtc DATETIME,IsDeleted INTEGER DEFAULT 0);
CREATE INDEX IF NOT EXISTS IX_Intake_Serial ON Intake(Serial);
INSERT INTO SchemaVersion(Version) SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM SchemaVersion);
CREATE TABLE IF NOT EXISTS Settings(Key TEXT PRIMARY KEY,Value TEXT);
